import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';
import { Claim } from './claims.service';

export type Grade = 'A' | 'B' | 'C';

export const GRADES: readonly Grade[] = ['A', 'B', 'C'];

/** A grade a person was given and the date it is in force from (YYYY-MM-DD); null when it applies
 *  from the beginning of time (the first grade they were given). */
export interface PersonGrade {
  grade: Grade;
  from: string | null;
}

export interface Person {
  id: number;
  name: string;
  /** The grade in force on the sheet's today when the person was read. */
  grade: Grade;
  /** Every grade the person was given, by from-date (the one with none first). */
  grades: PersonGrade[];
  /** Raised each time the person is saved. */
  version: number;
  /** Retired as soon as a retirement date is set, whatever the date. */
  retired: boolean;
  /** The date the person is retired from (YYYY-MM-DD); null while they are not retired. */
  retiredFrom: string | null;
  /** On hold: their OPEN claims count in no live total while held. */
  held: boolean;
}

/** A patron a person has named: another person on the same sheet. */
export interface Patron {
  id: number;
  personId: number;
  patronId: number;
}

/** What a quick-add made: the person the claim is for (added just now when the name was new) and
 *  the DRAFT claim. */
export interface QuickAdded {
  person: Person;
  claim: Claim;
}

export interface PersonFields {
  name: string;
  grade: Grade;
  /** On a save, the date the grade is given from (YYYY-MM-DD); null for the sheet's today. */
  gradeFrom?: string | null;
}

/** The grade in force on a date: the one with the latest from-date on or before it, or the first
 *  one given when none has; the latest given when there is no date. */
export function gradeOn(grades: PersonGrade[], date: string | null): Grade | null {
  let best: PersonGrade | null = null;
  for (const g of grades) {
    if (date !== null && g.from !== null && g.from > date) continue;
    if (best === null || (best.from ?? '') <= (g.from ?? '')) best = g;
  }
  return best?.grade ?? null;
}

// The people kept on a sheet, read from and written to the server.
@Injectable({ providedIn: 'root' })
export class PeopleService {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  list(sheet: string): Promise<Person[]> {
    return firstValueFrom(
      this.http.get<Person[]>(this.url(sheet), { headers: this.session.headers() }),
    );
  }

  add(sheet: string, fields: PersonFields): Promise<Person> {
    return firstValueFrom(
      this.http.post<Person>(this.url(sheet), fields, { headers: this.session.headers() }),
    );
  }

  /** Save the person as edited from `version`; refused with 409 and the person as now stored
   *  (`current`) when someone else has saved them since. */
  update(sheet: string, id: number, version: number, fields: PersonFields): Promise<Person> {
    return firstValueFrom(
      this.http.put<Person>(`${this.url(sheet)}/${id}`, { ...fields, version }, {
        headers: this.session.headers(),
      }),
    );
  }

  /** Retire the person from `from` (the sheet's today when null). */
  retire(sheet: string, id: number, from: string | null): Promise<Person> {
    return firstValueFrom(
      this.http.post<Person>(`${this.url(sheet)}/${id}/retire`, { from }, {
        headers: this.session.headers(),
      }),
    );
  }

  /** Put the person on hold (`held` true) or take them off it; refused (409) when they already are. */
  hold(sheet: string, id: number, held: boolean): Promise<Person> {
    return firstValueFrom(
      this.http.post<Person>(`${this.url(sheet)}/${id}/hold`, { held }, {
        headers: this.session.headers(),
      }),
    );
  }

  /** The sheet's patrons, in the order they were named. */
  patrons(sheet: string): Promise<Patron[]> {
    return firstValueFrom(
      this.http.get<Patron[]>(`${this.url(sheet)}/patrons`, { headers: this.session.headers() }),
    );
  }

  /** Name `patronId` as the person's patron; refused (409) for the person themselves or one already
   *  named. */
  addPatron(sheet: string, id: number, patronId: number): Promise<Patron> {
    return firstValueFrom(
      this.http.post<Patron>(`${this.url(sheet)}/${id}/patrons`, { patronId }, {
        headers: this.session.headers(),
      }),
    );
  }

  /** Add a DRAFT claim of `amount`, dated the sheet's today, for the person named `name`, adding
   *  them with grade A first when no one on the sheet has that name; all or nothing. */
  quickAdd(sheet: string, name: string, amount: string): Promise<QuickAdded> {
    return firstValueFrom(
      this.http.post<QuickAdded>(`/api/sheets/${encodeURIComponent(sheet)}/quick-add`, { name, amount }, {
        headers: this.session.headers(),
      }),
    );
  }

  private url(sheet: string): string {
    return `/api/sheets/${encodeURIComponent(sheet)}/people`;
  }
}
import { HttpErrorResponse } from '@angular/common/http';
import { Component, computed, inject, input, output, signal } from '@angular/core';
import { Session } from '../../core/session';
import { Period, PeriodsService } from './periods.service';

const DATE = /^\d{4}-\d{2}-\d{2}$/;

// The periods of the sheet, by from-date, each with the due-total of the counting claims dated in
// it (fixed once it is closed), whether it is closed, the buttons that close and reopen it, and the
// form that adds a period.
@Component({
  selector: 'app-periods',
  template: `
    <section aria-labelledby="periods-heading">
      <h2 id="periods-heading">Periods</h2>
      <form (submit)="submit($event)" aria-label="Period" data-testid="period-form">
        <label for="period-form-name">Name</label>
        <input
          id="period-form-name"
          data-testid="period-form-name"
          [value]="name()"
          (input)="name.set(value($event)); error.set(null)"
        />
        <label for="period-form-from">From</label>
        <input
          id="period-form-from"
          type="date"
          data-testid="period-form-from"
          [value]="from()"
          (input)="from.set(value($event)); error.set(null)"
        />
        <label for="period-form-to">To</label>
        <input
          id="period-form-to"
          type="date"
          data-testid="period-form-to"
          [value]="to()"
          (input)="to.set(value($event)); error.set(null)"
        />
        <button type="submit" data-testid="period-form-submit">Add period</button>
        @if (error(); as message) {
          <p role="alert" class="error" data-testid="period-form-error">{{ message }}</p>
        }
      </form>
      @if (sorted().length > 0) {
        <table data-testid="period-list">
          <thead>
            <tr>
              <th scope="col">Period</th>
              <th scope="col">From</th>
              <th scope="col">To</th>
              <th scope="col">Due</th>
              <th scope="col">Closed</th>
              <th scope="col"><span class="visually-hidden">Actions</span></th>
            </tr>
          </thead>
          <tbody>
            @for (p of sorted(); track p.id) {
              <tr [attr.data-testid]="'period-row-' + p.name">
                <td data-testid="period-name">{{ p.name }}</td>
                <td data-testid="period-from">{{ p.from }}</td>
                <td data-testid="period-to">{{ p.to }}</td>
                <td data-testid="period-due-total">{{ p.closed ? p.closedTotal : (dueTotals()[p.name] ?? '0.00') }}</td>
                <td data-testid="period-closed">{{ p.closed ? 'yes' : 'no' }}</td>
                <td>
                  @if (!p.closed) {
                    <button
                      type="button"
                      data-testid="period-close"
                      [attr.aria-label]="'Close period ' + p.name"
                      (click)="close(p)"
                    >
                      Close
                    </button>
                  }
                  <button
                    type="button"
                    data-testid="period-reopen"
                    [attr.aria-label]="'Reopen period ' + p.name"
                    (click)="reopen(p)"
                  >
                    Reopen
                  </button>
                  @if (rowErrors()[p.id]; as message) {
                    <p role="alert" class="error" data-testid="period-error">{{ message }}</p>
                  }
                </td>
              </tr>
            }
          </tbody>
        </table>
      }
    </section>
  `,
  styles: `
    form {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem;
      align-items: center;
      margin-bottom: 0.5rem;
    }
    .error {
      color: #a40000;
      margin: 0;
    }
    table {
      border-collapse: collapse;
      margin-bottom: 1rem;
    }
    .visually-hidden {
      position: absolute;
      width: 1px;
      height: 1px;
      overflow: hidden;
      clip: rect(0 0 0 0);
      white-space: nowrap;
    }
    th,
    td {
      text-align: left;
      padding: 0.25rem 0.75rem 0.25rem 0;
    }
  `,
})
export class Periods {
  private readonly session = inject(Session);
  private readonly service = inject(PeriodsService);

  /** The sheet's periods. */
  readonly periods = input.required<Period[]>();
  /** Each period's due-total, by name. */
  readonly dueTotals = input.required<Record<string, string>>();
  /** A period was added. */
  readonly added = output<Period>();
  /** A period was closed. */
  readonly closed = output<Period>();
  /** A period was reopened. */
  readonly reopened = output<Period>();

  protected readonly sorted = computed(() => [...this.periods()].sort((a, b) => a.from.localeCompare(b.from)));
  protected readonly name = signal('');
  protected readonly from = signal('');
  protected readonly to = signal('');
  protected readonly error = signal<string | null>(null);
  /** The error of the last refused action on each period, by period id. */
  protected readonly rowErrors = signal<Record<number, string>>({});
  /** A submit is waiting for its answer; another submit meanwhile is ignored. */
  private submitting = false;

  protected value(event: Event): string {
    return (event.target as HTMLInputElement).value;
  }

  /** Close the period, fixing its due-total; closing one already closed is refused with an error. */
  protected async close(period: Period): Promise<void> {
    this.rowErrors.update(({ [period.id]: _, ...rest }) => rest);
    const sheet = this.session.sheetId();
    if (!sheet) return;
    try {
      const closed = await this.service.close(sheet, period.id);
      if (this.session.sheetId() === sheet) this.closed.emit(closed);
    } catch {
      if (this.session.sheetId() !== sheet) return;
      this.rowErrors.update((errors) => ({ ...errors, [period.id]: 'That period could not be closed.' }));
    }
  }

  /** Reopen the period, making its due-total live again; refused with an error unless the user is a
   * steward and the period is closed. */
  protected async reopen(period: Period): Promise<void> {
    this.rowErrors.update(({ [period.id]: _, ...rest }) => rest);
    const sheet = this.session.sheetId();
    if (!sheet) return;
    try {
      const reopened = await this.service.reopen(sheet, period.id);
      if (this.session.sheetId() === sheet) this.reopened.emit(reopened);
    } catch (e) {
      if (this.session.sheetId() !== sheet) return;
      this.rowErrors.update((errors) => ({
        ...errors,
        [period.id]:
          e instanceof HttpErrorResponse && e.status === 403
            ? 'Only a steward can reopen a period.'
            : 'That period could not be reopened.',
      }));
    }
  }

  protected async submit(event: Event): Promise<void> {
    event.preventDefault();
    if (this.submitting) return;
    this.error.set(null);
    const sheet = this.session.sheetId();
    if (!sheet) return;
    const fields = { name: this.name().trim(), from: this.from().trim(), to: this.to().trim() };
    if (!/^\S+$/.test(fields.name)) {
      this.error.set('Type a name for the period, without spaces.');
      return;
    }
    if (!DATE.test(fields.from) || !DATE.test(fields.to)) {
      this.error.set('Type a from and a to date as YYYY-MM-DD.');
      return;
    }
    if (fields.to < fields.from) {
      this.error.set('The to-date must not be before the from-date.');
      return;
    }
    this.submitting = true;
    try {
      const period = await this.service.add(sheet, fields);
      if (this.session.sheetId() !== sheet) return;
      this.added.emit(period);
      this.name.set('');
      this.from.set('');
      this.to.set('');
    } catch (e) {
      if (this.session.sheetId() !== sheet) return;
      this.error.set(
        e instanceof HttpErrorResponse && e.status === 409
          ? 'Another period has that name or shares some of its dates.'
          : 'That period could not be added.',
      );
    } finally {
      this.submitting = false;
    }
  }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;

/**
 * The figures each person on a sheet shows — what they have claimed (their OPEN and SETTLED claims,
 * leaving out the OPEN ones while they are on hold)
 * and their due-total (the sum of what is due on those claims as each shows it, n/a when none has a figure and no rate of
 * their grade is in force on the sheet's today) — and the sheet's totals of them. A change that moves
 * any of them is followed in the audit by a ROLLUP line per person whose figures moved, then a TOTALS
 * line when the sheet's totals moved: take a {@link #snapshot} before the change, and
 * {@link #recordSince} it after the change has recorded its own lines.
 */
@Service
public class RollupService {

    /** A due-total shown when there is none. */
    public static final String NONE = "n/a";

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final Audit audit;

    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** A person's figures, as shown. */
    public record Figures(String name, String claimed, String dueTotal) {
    }

    /** The sheet's figures at one moment: each person's, by id in the order they were added, and the totals. */
    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal) {
    }

    /** The figures the sheet shows now. */
    @Transactional(propagation = Propagation.MANDATORY)
    public Snapshot snapshot(String sheetId) {
        LocalDate today = sheets.findById(sheetId).map(Sheet::getToday).orElse(null);
        List<Claim> all = claims.findBySheetIdOrderByIdDesc(sheetId);
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = zero();
        BigDecimal dueTotal = zero();
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            BigDecimal claimed = zero();
            BigDecimal due = zero();
            boolean any = false;
            for (Claim claim : all) {
                if (!claim.getPersonId().equals(person.getId()) || !countsLive(claim, person)) continue;
                claimed = claimed.add(claim.getAmount());
                BigDecimal figure = shownOf(claim, person);
                if (figure == null) continue;
                due = due.add(figure);
                any = true;
            }
            boolean rated = today != null && rates.findInForce(sheetId, person.gradeOn(today), today).isPresent();
            claimedTotal = claimedTotal.add(claimed);
            if (any || rated) dueTotal = dueTotal.add(due);
            figures.put(person.getId(), new Figures(person.getName(), text(claimed), any || rated ? text(due) : NONE));
        }
        return new Snapshot(figures, text(claimedTotal), text(dueTotal));
    }

    /** Record the ROLLUP and TOTALS lines for the figures that moved since {@code before}. */
    @Transactional(propagation = Propagation.MANDATORY)
    public void recordSince(String sheetId, String user, Snapshot before) {
        Snapshot after = snapshot(sheetId);
        after.people().forEach((id, now) -> {
            Figures then = before.people().get(id);
            if (then != null && then.claimed().equals(now.claimed()) && then.dueTotal().equals(now.dueTotal())) return;
            audit.change("ROLLUP", sheetId, user, "person=" + now.name(), "claimed=" + now.claimed(),
                    "due-total=" + now.dueTotal());
        });
        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
                || !Objects.equals(before.dueTotal(), after.dueTotal())) {
            audit.change("TOTALS", sheetId, user, "claimed-total=" + after.claimedTotal(),
                    "due-total=" + after.dueTotal());
        }
    }

    /** Whether the claim counts in the live totals: OPEN or SETTLED, but not OPEN while its person
     * is on hold. */
    public static boolean countsLive(Claim claim, Person person) {
        return claim.getStatus().counts() && !(person.isHeld() && claim.getStatus() == ClaimStatus.OPEN);
    }

    /** The figure the claim shows and totals now: what was fixed when it was settled at a rate;
     * otherwise the figure a statement bound it to; otherwise what is due on it at its person's rate.
     * Null when it has no figure. */
    public BigDecimal figureOf(Claim claim, Person person) {
        if (claim.getStatus() == ClaimStatus.SETTLED && claim.getSettledDue() != null) return claim.getSettledDue();
        if (claim.isStated()) return claim.getStatedDue();
        return dueOf(claim, person);
    }

    /** What is due on the claim as it shows and totals now: its figure, plus its late charge; null when
     * it has no figure. */
    public BigDecimal shownOf(Claim claim, Person person) {
        BigDecimal figure = figureOf(claim, person);
        return figure == null ? null : figure.add(lateChargeOf(claim, figure));
    }

    /** The late charge on an OPEN claim whose figure is {@code figure}: the sheet's late percent of that
     * figure for every full 30 days the claim is overdue (past its due-by, its date plus the sheet's
     * terms, on the sheet's today), rounded half to even to two decimals; 0.00 on a claim not OPEN or
     * not overdue, and on a correction. A statement never binds it: it follows the sheet's today until the claim is settled. */
    public BigDecimal lateChargeOf(Claim claim, BigDecimal figure) {
        if (claim.getStatus() != ClaimStatus.OPEN || claim.isCorrection()) return zero();
        Sheet sheet = sheets.findById(claim.getSheetId()).orElse(null);
        if (sheet == null) return zero();
        LocalDate dueBy = claim.getDate().plusDays(sheet.getTerms());
        long periods = Math.max(0, ChronoUnit.DAYS.between(dueBy, sheet.getToday())) / 30;
        return figure.multiply(sheet.getLatePct()).multiply(BigDecimal.valueOf(periods)).movePointLeft(2)
                .setScale(2, RoundingMode.HALF_EVEN);
    }

    /** What is due on the claim at its person's rate in force on the claim's date: amount times pct,
     * divided by 100, rounded half to even to two decimals, and at least the sheet's floor (a correction,
     * whose due is negative, has no floor); null when no
     * rate of the grade in force for them on the claim's date applies then. */
    public BigDecimal dueOf(Claim claim, Person person) {
        BigDecimal floor = sheets.findById(claim.getSheetId()).map(Sheet::getFloor).orElse(zero());
        return rates.findInForce(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate())
                .map(Rate::getPct)
                .map(pct -> claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN))
                .map(due -> claim.isCorrection() ? due : due.max(floor))
                .orElse(null);
    }

    private static BigDecimal zero() {
        return BigDecimal.ZERO.setScale(2);
    }

    private static String text(BigDecimal value) {
        return value.setScale(2, RoundingMode.HALF_EVEN).toPlainString();
    }
}
package net.officefloor.hq.app.person;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import org.springframework.http.HttpStatus;
import org.springframework.orm.ObjectOptimisticLockingFailureException;
import org.springframework.http.ResponseEntity;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

/** The people on a sheet. The signed-in user's name travels in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}/people")
@Validated
public class PersonController {

    /** A grade a person was given and the date it is in force from (null: the beginning of time). */
    public record GradeView(String grade, LocalDate from) {
        public static GradeView of(PersonGrade grade) {
            return new GradeView(grade.getGrade(), grade.getFrom());
        }
    }

    /** A person: the grade in force on the sheet's {@code today}, and every grade they were given by
     * from-date; {@code retiredFrom} is null while they are not retired. */
    public record PersonView(long id, String name, String grade, List<GradeView> grades, long version,
            boolean retired, LocalDate retiredFrom, boolean held) {
        public static PersonView of(Person person, LocalDate today) {
            return new PersonView(person.getId(), person.getName(), person.gradeOn(today),
                    person.getGrades().stream().map(GradeView::of).toList(), person.getVersion(),
                    person.isRetired(), person.getRetiredFrom(), person.isHeld());
        }
    }

    /** A patron a person has named. */
    public record PatronView(long id, long personId, long patronId) {
        public static PatronView of(PersonPatron patron) {
            return new PatronView(patron.getId(), patron.getPersonId(), patron.getPatronId());
        }
    }

    /** The person to be named as a patron. */
    public record PatronRequest(@NotNull Long patronId) {
    }

    /** The date a person is retired from (the sheet's today when left out). */
    public record RetireRequest(LocalDate from) {
    }

    /** Whether the person is to be on hold (true) or taken off it (false). */
    public record HoldRequest(@NotNull Boolean held) {
    }

    /** A person's name (not blank; kept without the spaces around it and unique on the sheet
     * without regard to case) and grade, one of A, B or C, given from {@code gradeFrom} on a save (the
     * sheet's today when left out; a person's first grade applies from the beginning of time). */
    public record PersonRequest(
            @NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade,
            LocalDate gradeFrom,
            Long version) {
    }

    /** A save refused because the person was saved by someone else since the editor loaded them:
     * the person as now stored. */
    public record StaleView(String error, PersonView current) {
    }

    private final PersonService service;

    public PersonController(PersonService service) {
        this.service = service;
    }

    @GetMapping
    public List<PersonView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        LocalDate today = service.today(sheetId.trim());
        return service.list(sheetId.trim()).stream().map(person -> PersonView.of(person, today)).toList();
    }

    @GetMapping("/patrons")
    public List<PatronView> patrons(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return service.patrons(sheetId.trim()).stream().map(PatronView::of).toList();
    }

    @PostMapping("/{personId}/patrons")
    @ResponseStatus(HttpStatus.CREATED)
    public PatronView addPatron(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid PatronRequest request) {
        return PatronView.of(service.addPatron(sheetId.trim(), user.trim(), personId, request.patronId()));
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PersonView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid PersonRequest request) {
        return view(sheetId, service.add(sheetId.trim(), user.trim(), request.name(), request.grade()));
    }

    @PutMapping("/{personId}")
    public PersonView update(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid PersonRequest request) {
        if (request.version() == null) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "version is required");
        }
        try {
            return view(sheetId, service.update(sheetId.trim(), user.trim(), personId, request.version(),
                    request.name(), request.grade(), request.gradeFrom()));
        } catch (ObjectOptimisticLockingFailureException e) {
            // Another save of the person committed while this one was under way.
            throw new PersonStaleException(service.get(sheetId.trim(), personId));
        }
    }

    @PostMapping("/{personId}/retire")
    public PersonView retire(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody(required = false) RetireRequest request) {
        return view(sheetId, service.retire(sheetId.trim(), user.trim(), personId,
                request == null ? null : request.from()));
    }

    @PostMapping("/{personId}/hold")
    public PersonView hold(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid HoldRequest request) {
        return view(sheetId, service.hold(sheetId.trim(), user.trim(), personId, request.held()));
    }

    @ExceptionHandler(PersonStaleException.class)
    public ResponseEntity<StaleView> stale(PersonStaleException e) {
        Person current = e.getCurrent();
        return ResponseEntity.status(HttpStatus.CONFLICT)
                .body(new StaleView("stale", PersonView.of(current, service.today(current.getSheetId()))));
    }

    /** The person as the sheet shows them on its today. */
    private PersonView view(String sheetId, Person person) {
        return PersonView.of(person, service.today(sheetId.trim()));
    }
}

