294	  private readonly statementsService = inject(StatementsService);
295	  private readonly periodsService = inject(PeriodsService);
296	
297	  protected readonly grades = GRADES;
298	  protected readonly money = money;
299	  protected readonly people = signal<Person[]>([]);
300	  /** Whether retired people are listed; off when the screen is first opened, kept across sheet loads. */
301	  protected readonly showRetired = signal(false);
302	  /** The people listed: everyone, or only those not retired unless "show retired" is on. */
303	  protected readonly shownPeople = computed(() =>
304	    this.showRetired() ? this.people() : this.people().filter((p) => !p.retired),
305	  );
306	  /** The retire-from date typed on each person's row, by person id. */
307	  protected readonly retireDates = signal<Record<number, string>>({});
308	  /** The sheet's claims, newest first. */
309	  protected readonly claims = signal<Claim[]>([]);
310	  private readonly claimsByPerson = computed(() => {
311	    const by = new Map<number, Claim[]>();
312	    for (const c of this.claims()) by.set(c.personId, [...(by.get(c.personId) ?? []), c]);
313	    return by;
314	  });
315	  protected readonly claimedTotal = computed(() =>
316	    money(this.people().reduce((sum, p) => sum + this.claimedCentsOf(p), 0)),
317	  );
318	  /** The sheet's statements, in the order they were taken. */
319	  protected readonly statements = signal<Statement[]>([]);
320	  private readonly statementsByPerson = computed(() => {
321	    const by = new Map<number, Statement[]>();
322	    for (const s of this.statements()) by.set(s.personId, [...(by.get(s.personId) ?? []), s]);
323	    return by;
324	  });
325	  /** The sheet's patrons, in the order they were named. */
326	  protected readonly patrons = signal<Patron[]>([]);
327	  /** The patron chosen on each person's row (a person id), by person id. */
328	  protected readonly patronChoices = signal<Record<number, string>>({});
329	  /** The error of the last refused patron added on each person's row, by person id. */
330	  protected readonly patronErrors = signal<Record<number, string>>({});
331	  /** Each person's patrons' names, sorted and comma separated, by person id. */
332	  private readonly patronNames = computed(() => {
333	    const byId = new Map(this.people().map((p) => [p.id, p.name]));
334	    const by = new Map<number, string[]>();
335	    for (const pt of this.patrons()) {
336	      const name = byId.get(pt.patronId);
337	      if (name !== undefined) by.set(pt.personId, [...(by.get(pt.personId) ?? []), name]);
338	    }
339	    return new Map([...by].map(([id, names]) => [id, names.sort().join(', ')]));
340	  });
341	  /** Each person's backing, by person id: their patrons' due-totals added up (n/a ones skipped). */
342	  private readonly backings = computed(() => {
343	    const byId = new Map(this.people().map((p) => [p.id, p]));
344	    const by = new Map<number, number>();
345	    for (const pt of this.patrons()) {
346	      const patron = byId.get(pt.patronId);
347	      const due = patron === undefined ? null : this.dueCentsOf(patron);
348	      by.set(pt.personId, (by.get(pt.personId) ?? 0) + (due ?? 0));
349	    }
350	    return by;
351	  });
352	  /** The error of the last refused action on each person's row, by person id. */
353	  protected readonly rowErrors = signal<Record<number, string>>({});
354	  /** The sheet's rates, by grade. */
355	  protected readonly rates = signal<Rate[]>([]);
356	  /** The sheet's floor, in cents: the least a claim's live due can be. */
357	  protected readonly floor = signal(FLOOR_CENTS);
358	  /** The sheet's terms, in days: how long after its date a claim is due by. */
359	  protected readonly terms = signal(TERMS_DAYS);
360	  /** The sheet's late percent, with two decimals. */
361	  protected readonly latePct = signal(LATE_PCT);
362	  /** What the claims' late charges are worked from. */
363	  private readonly lateness = computed<Lateness>(() => ({
364	    terms: this.terms(),
365	    today: this.session.today(),
366	    latePct: this.latePct(),
367	  }));
368	  /** The sheet's periods. */
369	  protected readonly periods = signal<Period[]>([]);
370	  /** Each period's due-total, by name: what is due on the OPEN and SETTLED claims dated in it, as
371	   *  each claim shows it (a claim with nothing due is skipped). */
372	  protected readonly periodDueTotals = computed(() => {
373	    const sums: Record<string, number> = {};
374	    for (const p of this.periods()) sums[p.name] = 0;
375	    for (const person of this.people()) {
376	      for (const c of this.claimsOf(person.id)) {
377	        if (!this.countsLive(c, person)) continue;
378	        const period = periodOn(this.periods(), c.date);
379	        if (period === null) continue;
380	        sums[period.name] += claimShownCents(c, this.rates(), person.grades, this.floor(), this.lateness()) ?? 0;
