390	  /** How many of everyone's counting claims are overdue, and what is due on them, in cents. */
391	  protected readonly overdueTotal = computed(() =>
392	    this.people().reduce(
393	      (sum, p) => {
394	        const o = this.overdueOf(p);
395	        return { count: sum.count + o.count, cents: sum.cents + o.cents };
396	      },
397	      { count: 0, cents: 0 },
398	    ),
399	  );
