488	  /** Retire the person from the date typed on their row (the sheet's today when blank). */
489	  protected async retire(person: Person): Promise<void> {
490	    this.clearRowError(person.id);
491	    const sheet = this.sheet();
492	    if (!sheet) return;
493	    const from = (this.retireDates()[person.id] ?? '').trim();
494	    if (from !== '' && !/^\d{4}-\d{2}-\d{2}$/.test(from)) {
495	      this.rowErrors.update((errors) => ({ ...errors, [person.id]: 'Type a date as YYYY-MM-DD.' }));
496	      return;
497	    }
