499	      const retired = await this.service.retire(sheet, person.id, from || null);
500	      if (this.sheet() !== sheet) return;
501	      this.put(retired);
502	      this.retireDates.update(({ [person.id]: _, ...rest }) => rest);
503	    } catch {
504	      if (this.sheet() !== sheet) return;
505	      this.rowErrors.update((errors) => ({ ...errors, [person.id]: 'That person could not be retired.' }));
