529	    this.clearRowError(person.id);
530	    const sheet = this.sheet();
531	    if (!sheet) return;
532	    const choice = this.patronChoices()[person.id] ?? '';
533	    if (choice === '') {
534	      this.patronErrors.update((errors) => ({ ...errors, [person.id]: 'Choose a patron.' }));
535	      return;
536	    }
537	    try {
538	      const added = await this.service.addPatron(sheet, person.id, Number(choice));
539	      if (this.sheet() !== sheet) return;
540	      this.patrons.update((list) => [...list, added]);
541	      this.patronChoices.update(({ [person.id]: _, ...rest }) => rest);
542	    } catch {
543	      if (this.sheet() !== sheet) return;
544	      this.patronErrors.update((errors) => ({
545	        ...errors,
546	        [person.id]: 'That person cannot be added as a patron.',
547	      }));
548	    }
549	  }
550	
551	  /** Put the person on hold, or take them off it when held. */
552	  protected async toggleHold(person: Person): Promise<void> {
553	    this.clearRowError(person.id);
554	    const sheet = this.sheet();
555	    if (!sheet) return;
556	    try {
557	      const saved = await this.service.hold(sheet, person.id, !person.held);
558	      if (this.sheet() !== sheet) return;
559	      this.put(saved);
560	    } catch {
561	      if (this.sheet() !== sheet) return;
562	      this.rowErrors.update((errors) => ({
563	        ...errors,
564	        [person.id]: person.held ? 'That person could not be released.' : 'That person could not be held.',
565	      }));
566	    }
567	  }
568	
569	  /** Whether the claim counts in the live totals: OPEN or SETTLED, but not OPEN while its person is
570	   *  on hold. */
571	  private countsLive(claim: Claim, person: Person): boolean {
572	    return counts(claim) && !(person.held && claim.status === 'OPEN');
573	  }
574	
575	  protected claimedOf(person: Person): string {
576	    return money(this.claimedCentsOf(person));
577	  }
578	
579	  /** What the person's OPEN and SETTLED claims add up to (OPEN ones left out while they are on
580	   *  hold); drafts and voided claims do not count. */
581	  private claimedCentsOf(person: Person): number {
582	    return this.claimsOf(person.id).reduce((sum, c) => sum + (this.countsLive(c, person) ? cents(c.amount) : 0), 0);
583	  }
584	
585	  /** The grade's rate in force on the sheet's today. */
586	  private rateOf(grade: Grade | null): string | null {
587	    const today = this.session.today();
588	    return today === null || grade === null ? null : rateOn(this.rates(), grade, today);
589	  }
590	
591	  /** The person's grade in force on the sheet's today. */
592	  protected gradeNow(person: Person): Grade {
593	    return gradeOn(person.grades, this.session.today()) ?? person.grade;
594	  }
595	
596	  /** The sum of what is due on each of the person's OPEN and SETTLED claims, as each claim shows
597	   *  it (a claim with nothing due is skipped); n/a when no rate of their grade applies on the
598	   *  sheet's today and none of their claims has a figure. */
599	  protected dueTotalOf(person: Person): string | null {
600	    const due = this.dueCentsOf(person);
601	    return due === null ? null : money(due);
602	  }
603	
604	  private dueCentsOf(person: Person): number | null {
605	    let sum = 0;
606	    let any = false;
607	    for (const c of this.claimsOf(person.id)) {
608	      if (!this.countsLive(c, person)) continue;
609	      const due = claimShownCents(c, this.rates(), person.grades, this.floor(), this.lateness());
610	      if (due === null) continue;
611	      sum += due;
612	      any = true;
613	    }
614	    return any || this.rateOf(this.gradeNow(person)) !== null ? sum : null;
615	  }
616	
617	  /** How many of the person's counting claims are overdue, and the sum of what is due on them, in
618	   *  cents, as each claim shows it (a claim with nothing due adds nothing). */
619	  protected overdueOf(person: Person): { count: number; cents: number } {
620	    let count = 0;
621	    let sum = 0;
622	    const today = this.session.today();
623	    for (const c of this.claimsOf(person.id)) {
624	      if (!this.countsLive(c, person) || !overdue(c, this.terms(), today)) continue;
625	      count++;
626	      sum += claimShownCents(c, this.rates(), person.grades, this.floor(), this.lateness()) ?? 0;
627	    }
628	    return { count, cents: sum };
629	  }
630	
631	  protected periodAdded(period: Period): void {
632	    this.periods.update((list) => [...list, period]);
633	  }
634	
635	  /** Put a closed or reopened period in its place. */
636	  protected periodClosed(period: Period): void {
637	    this.periods.update((list) => list.map((p) => (p.id === period.id ? period : p)));
638	  }
639	
640	  /** Put a set rate in place of the grade's old one for the same from-date. */
641	  protected rateSaved(rate: Rate): void {
642	    this.rates.update((list) => [
643	      ...list.filter((r) => r.grade !== rate.grade || r.from !== rate.from),
644	      rate,
645	    ]);
646	  }
647	
648	  /** Put an added claim first, or a saved one in its place. */
649	  protected claimSaved(claim: Claim): void {
650	    this.claims.update((list) =>
651	      list.some((c) => c.id === claim.id)
652	        ? list.map((c) => (c.id === claim.id ? claim : c))
653	        : [claim, ...list],
654	    );
655	  }
656	
657	  protected edit(person: Person): void {
658	    this.clearRowError(person.id);
659	    this.editingId.set(person.id);
660	    this.editingVersion = person.version;
661	    this.name.set(person.name);
662	    this.grade.set(this.gradeNow(person));
663	    this.gradeFrom.set('');
664	    this.error.set(null);
665	  }
666	
667	  protected reset(): void {
668	    this.editingId.set(null);
669	    this.name.set('');
670	    this.grade.set('A');
671	    this.gradeFrom.set('');
672	    this.error.set(null);
673	  }
674	
675	  protected async submit(event: Event): Promise<void> {
676	    event.preventDefault();
677	    if (this.submitting) return;
678	    this.error.set(null);
679	    const sheet = this.sheet();
680	    if (!sheet) return;
681	    const fields = { name: this.name(), grade: this.grade() };
682	    if (!fields.name.trim()) {
683	      this.error.set('Type a name for the person.');
684	      return;
685	    }
686	    const id = this.editingId();
687	    this.submitting = true;
688	    try {
689	      if (id === null) {
690	        const added = await this.service.add(sheet, fields);
691	        if (this.sheet() === sheet) this.people.update((list) => [...list, added]);
692	      } else {
693	        const saved = await this.service.update(sheet, id, this.editingVersion, {
694	          ...fields,
695	          gradeFrom: this.gradeFrom() || null,
696	        });
697	        if (this.sheet() === sheet) this.put(saved);
698	      }
699	      if (this.sheet() === sheet) this.reset();
700	    } catch (e) {
701	      if (this.sheet() !== sheet) return;
702	      const current = this.staleOf(e);
703	      if (current !== null) {
704	        // Someone else saved the person since the editor loaded them: show them as now stored.
705	        this.put(current);
706	        if (this.editingId() === current.id) {
707	          this.editingVersion = current.version;
708	          this.name.set(current.name);
709	          this.grade.set(this.gradeNow(current));
710	        }
711	        this.error.set('Someone else saved this person since you opened it; their changes are shown.');
712	        return;
713	      }
714	      if (e instanceof HttpErrorResponse && e.status === 409) {
715	        this.error.set('Another person on the sheet already has that name.');
716	        return;
717	      }
718	      this.error.set(id === null ? 'That person could not be added.' : 'That person could not be saved.');
719	    } finally {
720	      this.submitting = false;
721	    }
722	  }
723	
724	  /** Add a DRAFT claim for the named person, adding them (grade A) first when the name is new. */
725	  protected async quickAdd(event: Event): Promise<void> {
726	    event.preventDefault();
727	    if (this.quickAdding) return;
728	    this.quickError.set(null);
729	    const sheet = this.sheet();
730	    if (!sheet) return;
731	    const name = this.quickName();
732	    if (!name.trim()) {
733	      this.quickError.set('Type a name for the claim.');
734	      return;
735	    }
736	    this.quickAdding = true;
737	    try {
738	      const added = await this.service.quickAdd(sheet, name, this.quickAmount());
739	      if (this.sheet() !== sheet) return;
740	      this.people.update((list) =>
741	        list.some((p) => p.id === added.person.id) ? list : [...list, added.person],
742	      );
743	      this.claimSaved(added.claim);
744	      this.quickName.set('');
745	      this.quickAmount.set('');
746	    } catch (e) {
747	      if (this.sheet() !== sheet) return;
748	      this.quickError.set(
749	        e instanceof HttpErrorResponse && e.status === 423
750	          ? 'That claim falls in a closed period.'
751	          : e instanceof HttpErrorResponse && e.status === 422
752	            ? 'That claim is dated after the person retired.'
753	            : 'That claim could not be added.',
754	      );
755	    } finally {
756	      this.quickAdding = false;
757	    }
758	  }
759	
760	  /** Put a saved person in place of their old row. */
761	  private put(person: Person): void {
762	    this.people.update((list) => list.map((p) => (p.id === person.id ? person : p)));
763	  }
764	
765	  /** The person as now stored, when a save was refused for being made from an older version. */
766	  private staleOf(e: unknown): Person | null {
767	    if (!(e instanceof HttpErrorResponse) || e.status !== 409) return null;
768	    const body = e.error as { error?: unknown; current?: Person } | null;
769	    return body?.error === 'stale' && body.current ? body.current : null;
770	  }
771	
772	  private async read(sheet: string): Promise<void> {
773	    try {
774	      const [list, claims, rates, statements, periods, settings, patrons] = await Promise.all([
775	        this.service.list(sheet),
776	        this.claimsService.list(sheet),
777	        this.ratesService.list(sheet),
778	        this.statementsService.list(sheet),
779	        this.periodsService.list(sheet),
780	        this.settingsService.get(sheet),
781	        this.service.patrons(sheet),
782	      ]);
783	      if (this.sheet() === sheet) {
784	        this.floor.set(cents(settings.floor));
785	        this.terms.set(settings.terms);
786	        this.latePct.set(settings.latePct);
787	        this.rates.set(rates);
788	        this.periods.set(periods);
789	        this.statements.set(statements);
790	        this.claims.set(claims);
791	        this.patrons.set(patrons);
792	        this.people.set(list);
793	      }
794	    } catch {
795	      // The sheet's people could not be read; the list stays empty.
796	    }
797	  }
798	}
